#include <atomic>
#include <iostream>
#include <mutex>
#include <thread>
#include <utility>

class Inventory {
    std::mutex mutex_;
    int remaining_=100;
    int accepted_=0;
public:
    bool reserve(int quantity) {
        if(quantity<=0 || quantity>100)return false;
        std::lock_guard<std::mutex> guard(mutex_);
        if(quantity>remaining_)return false;
        remaining_-=quantity;
        accepted_+=quantity;
        return true;
    }
    std::pair<int,int> snapshot() {
        std::lock_guard<std::mutex> guard(mutex_);
        return {remaining_,accepted_};
    }
};

int main() {
    Inventory inventory;
    std::atomic<int> attempts{0};
    auto work=[&inventory,&attempts] {
        for(int i=0;i<75;++i) {
            (void)inventory.reserve(1);
            attempts.fetch_add(1,std::memory_order_seq_cst);
        }
    };
    {
        std::jthread first(work);
        std::jthread second(work);
    }
    const auto [remaining,accepted]=inventory.snapshot();
    std::cout<<remaining<<' '<<accepted<<'\n';
    std::cout<<attempts.load(std::memory_order_seq_cst)<<'\n';
}

def split_atomic_reservation(schedule):
    # One-thread model of individually atomic load/decrement events, not a whole transaction.
    if type(schedule) is not str or len(schedule)!=4 or schedule.count("A")!=2 or schedule.count("B")!=2:
        raise ValueError("expected two steps each for A and B")
    available=1
    accepted=0
    steps={"A":0,"B":0}
    allowed={}
    for worker in schedule:
        if steps[worker]==0:
            allowed[worker]=available>0
        elif allowed[worker]:
            available-=1
            accepted+=1
        steps[worker]+=1
    return available,accepted

print(split_atomic_reservation("AABB"))
print(split_atomic_reservation("ABAB"))
